'suduiraut|2019':{v:'Pressurage long en grappes entières en pressoir pneumatique pendant 2h30, suivi d’un pressurage d’1h en pressoir vertical. - Débourbage à froid 10°C. - Fermentation en barriques avec 50 % de bois neuf et thermorégulation unitaire des barriques entre 18 et 24°C.',src:'Chateau_Suduiraut_2019_Premier_Cru_Classe_en_1855_Sauternes--Axa_Millesimes--vin_co_M1JC9F.pdf',label:'VINIFICATION - ',lang:'fr'},
'suduiraut|2023':{v:'Pressurage pneumatique doux et long : environ 3h, - Puis pressurage verticale : environ 50 min pour extraire la partie la plus concentrée, - Débourbage à froid 10 °C, - Fermentation',src:'Chateau_Suduiraut_2023--Axa_Millesimes--vin_co_CG027F.pdf',label:'VINIFICATION - ',lang:'fr'},
'suduiraut|2024':{v:'Gentle and long pneumatic pressing: about 3 hours, - Then vertical pressing: about 50 minutes to extract the most concentrated part, - Cold settling at 10°C',src:'ft_chateau-suduiraut-2024_ft-en-chateau-suduiraut-2024-premier-cru-classe-en-1855-sauternes.pdf',label:'WINEMAKING - ',lang:'en'},
